use clap::{Parser, ValueEnum};
use std::path::PathBuf;
use anyhow::Result;

#[derive(Parser, Debug)]
#[command(
    name = "onefetch",
    version = "2.25.0",
    about = "Command-line Git information tool",
    long_about = "Onefetch is a command-line tool that displays project information and code\nstatistics for a local Git repository directly in your terminal."
)]
struct Args {
    #[arg(
        value_name = "INPUT",
        help = "Run as if onefetch was started in <input> instead of the current working directory"
    )]
    input: Option<PathBuf>,

    #[command(flatten)]
    info_opts: InfoOptions,

    #[command(flatten)]
    text_opts: TextOptions,

    #[command(flatten)]
    ascii_opts: AsciiOptions,

    #[command(flatten)]
    image_opts: ImageOptions,

    #[command(flatten)]
    visuals_opts: VisualsOptions,

    #[command(flatten)]
    dev_opts: DeveloperOptions,

    #[command(flatten)]
    other_opts: OtherOptions,
}

#[derive(Parser, Debug)]
#[command(next_help_heading = "INFO")]
struct InfoOptions {
    #[arg(
        short = 'd',
        long,
        value_name = "FIELD",
        help = "Allows you to disable FIELD(s) from appearing in the output"
    )]
    disabled_fields: Vec<String>,

    #[arg(long, help = "Hides the title")]
    no_title: bool,

    #[arg(long, value_name = "NUM", default_value = "3", help = "Maximum NUM of authors to be shown")]
    number_of_authors: usize,

    #[arg(long, value_name = "NUM", default_value = "6", help = "Maximum NUM of languages to be shown")]
    number_of_languages: usize,

    #[arg(long, value_name = "NUM", default_value = "3", help = "Maximum NUM of file churns to be shown")]
    number_of_file_churns: usize,

    #[arg(
        long,
        value_name = "NUM",
        help = "Minimum NUM of commits from HEAD used to compute the churn summary\n\nBy default, the actual value is non-deterministic due to time-based computation and will\nbe displayed under the info title \"Churn (NUM)\""
    )]
    churn_pool_size: Option<usize>,

    #[arg(short = 'e', long, value_name = "EXCLUDE", help = "Ignore all files & directories matching EXCLUDE")]
    exclude: Vec<String>,

    #[arg(long, value_name = "REGEX", help = "Exclude [bot] commits. Use <REGEX> to override the default pattern")]
    no_bots: Option<Option<String>>,

    #[arg(long, help = "Ignores merge commits")]
    no_merges: bool,

    #[arg(short = 'E', long, help = "Show the email address of each author")]
    email: bool,

    #[arg(long, help = "Display repository URL as HTTP")]
    http_url: bool,

    #[arg(long, help = "Hide token in repository URL")]
    hide_token: bool,

    #[arg(long, help = "Count hidden files and directories")]
    include_hidden: bool,

    #[arg(
        short = 'T',
        long,
        value_name = "TYPE",
        default_values = &["programming", "markup"],
        help = "Filters output by language type"
    )]
    r#type: Vec<String>,
}

