        help = "Takes a non-empty STRING as input to replace the ASCII logo\n\nIt is possible to pass a generated STRING by command substitution\n\nFor example:\n\n'--ascii-input \"$(fortune | cowsay -W 25)\"'"
    )]
    ascii_input: Option<String>,

