#[derive(Parser, Debug)]
#[command(next_help_heading = "IMAGE")]
struct ImageOptions {
    #[arg(short = 'i', long, value_name = "IMAGE", help = "Path to the IMAGE file")]
    image: Option<PathBuf>,

    #[arg(
        long,
        value_name = "PROTOCOL",
        help = "Which image PROTOCOL to use"
    )]
    image_protocol: Option<String>,

    #[arg(
        long,
