fn run_onefetch(path: &PathBuf, args: Args) -> Result<()> {
    // Open git repository
    let repo = git2::Repository::discover(path)?;

    // Generate and output the information
    if let Some(format) = args.dev_opts.output {
        match format.as_str() {
            "json" => output_json(&repo, &args)?,
            "yaml" => output_yaml(&repo, &args)?,
            _ => anyhow::bail!("Unknown output format: {}", format),
        }
    } else {
        output_text(&repo, &args)?;
    }

    Ok(())
}

fn output_text(repo: &git2::Repository, args: &Args) -> Result<()> {
    use std::io::Write;

    // Set up terminal
    print!("\x1b[?7l");
    std::io::stdout().flush()?;

    let info = gather_info(repo, args)?;

    // Print title
    if !args.info_opts.no_title {
        print_title(&info, args)?;
    }

    // Print info fields
    print_info_fields(&info, args)?;

    // Print color palette
    if !args.visuals_opts.no_color_palette {
        print_color_palette()?;
    }

    // Reset terminal
    print!("\x1b[?7h");
    std::io::stdout().flush()?;

    Ok(())
}

