        return Ok(());
    }

    if let Some(shell) = &args.dev_opts.generate {
        print_completions(shell);
        return Ok(());
    }

    // Otherwise, work with git repository
    let path = args.input.unwrap_or_else(|| PathBuf::from("."));
    run_onefetch(&path, args)?;

    Ok(())
