    println!("        \"headRefs\": {{");
    println!("          \"shortCommitId\": \"{}\",", info.current_commit);
    println!("          \"refs\": [\"{}\"]\n        }}", info.current_branch);
    println!("      }}");
    println!("    }}");

    println!("  ]");
    println!("}}");

    Ok(())
}

