            let name = lines[i].trim().to_string();
            let email = lines[i + 1].trim().to_string();
            if !name.is_empty() {
                author_map.entry(name.clone())
                    .and_modify(|a| a.commits += 1)
                    .or_insert_with(|| Author {
                        name,
                        email,
                        commits: 1,
                    });
            }
        }
    }

    // Sort authors by commit count
    let mut sorted_authors: Vec<_> = author_map.into_values().collect();
    sorted_authors.sort_by(|a, b| b.commits.cmp(&a.commits));

    info.total_authors = sorted_authors.len();
    info.authors = sorted_authors.into_iter()
        .take(opts.number_of_authors)
        .collect();

    // Get file churn information - get recently modified files
    let output = Command::new("git")
        .args(&["-C", &repo_path.display().to_string(), "log", "--name-only", "--pretty=format:"])
        .output()
        .map_err(|e| format!("Failed to run git: {}", e))?;

    let mut file_map: HashMap<String, usize> = HashMap::new();
    for line in String::from_utf8_lossy(&output.stdout).lines() {
        let line = line.trim();
        if !line.is_empty() {
            *file_map.entry(line.to_string()).or_insert(0) += 1;
        }
    }

    let mut sorted_files: Vec<_> = file_map.iter()
        .map(|(name, count)| (name.clone(), *count))
        .collect();
    sorted_files.sort_by(|a, b| b.1.cmp(&a.1));
    info.files = sorted_files;

    // Get file count
    let file_count = count_files_in_repo(repo_path)?;
    info.file_count = file_count;

    // Get repo size
    info.repo_size = calculate_repo_size(repo_path)?;

    // Get creation and last change dates
    info.created_date = "now".to_string();
    info.last_change_date = "now".to_string();

    Ok(info)
}

fn count_files_in_repo(repo_path: &Path) -> Result<usize, String> {
    let output = Command::new("git")
        .args(&["-C", &repo_path.display().to_string(), "ls-files"])
        .output()
        .map_err(|e| format!("Failed to run git: {}", e))?;

    let file_count = String::from_utf8_lossy(&output.stdout)
        .lines()
        .count();

    Ok(file_count)
}

fn calculate_repo_size(repo_path: &Path) -> Result<String, String> {
    let mut total_size: u64 = 0;

    for entry in fs::read_dir(repo_path).map_err(|e| format!("Failed to read dir: {}", e))? {
        let entry = entry.map_err(|e| format!("Failed to read entry: {}", e))?;
        let path = entry.path();

        if path.file_name().unwrap_or_default() == ".git" {
            continue;
        }

        if let Ok(metadata) = fs::metadata(&path) {
            if metadata.is_file() {
                total_size += metadata.len();
            }
        }
    }

    let size_str = if total_size < 1024 {
        format!("{} B", total_size)
    } else if total_size < 1024 * 1024 {
        format!("{} KB", total_size / 1024)
    } else {
        format!("{} MB", total_size / (1024 * 1024))
    };

    Ok(size_str)
}

fn output_text(info: &RepoInfo, opts: &Options) -> Result<(), String> {
    // Print escape sequence
    print!("\x1b[?7l");
    std::io::stdout().flush().ok();

    if !opts.no_title && !info.git_user.is_empty() {
        // Print title line: username ~ git version
        println!("\x1b[37;1m{}\x1b[0m \x1b[39;1m~\x1b[0m \x1b[37;1m{}\x1b[0m", 
            info.git_user, info.git_version);
        println!("\x1b[39m{}\x1b[39m", "-".repeat(29));
    }

    // Print fields
    if !is_field_disabled(&opts.disabled_fields, "head") {
        println!("\x1b[37;1mHEAD\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{} ({})\x1b[0m", 
            info.current_commit, info.current_branch);
    }

    if !is_field_disabled(&opts.disabled_fields, "created") {
        println!("\x1b[37;1mCreated\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}\x1b[0m", 
            info.created_date);
    }

    if !is_field_disabled(&opts.disabled_fields, "authors") && !info.authors.is_empty() {
        let label = if info.authors.len() == 1 { "Author" } else { "Authors" };
        let total_commits = info.total_commits.max(1);

        for (i, author) in info.authors.iter().enumerate() {
            let percentage = (author.commits * 100) / total_commits;
            if i == 0 {
                if opts.email {
                    println!("\x1b[37;1m{}\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}% {} <{}> {}\x1b[0m", 
                        label, percentage, author.name, author.email, author.commits);
                } else {
                    println!("\x1b[37;1m{}\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}% {} {}\x1b[0m", 
                        label, percentage, author.name, author.commits);
                }
            } else {
                if opts.email {
                    println!("         \x1b[39m{}% {} <{}> {}\x1b[0m", 
                        percentage, author.name, author.email, author.commits);
                } else {
                    println!("         \x1b[39m{}% {} {}\x1b[0m", 
                        percentage, author.name, author.commits);
                }
            }
        }
    }

    if !is_field_disabled(&opts.disabled_fields, "last-change") {
        println!("\x1b[37;1mLast change\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}\x1b[0m", 
            info.last_change_date);
    }

    if !is_field_disabled(&opts.disabled_fields, "commits") {
        println!("\x1b[37;1mCommits\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}\x1b[0m", 
            info.total_commits);
    }

    if !is_field_disabled(&opts.disabled_fields, "churn") && !info.files.is_empty() {
        let pool_size = info.files.len().max(1);
        for (i, (file, _)) in info.files.iter().take(opts.number_of_file_churns).enumerate() {
            if i == 0 {
                println!("\x1b[37;1mChurn ({})\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{} 1\x1b[0m", 
                    pool_size, file);
            } else {
                println!("         \x1b[39m{} 1\x1b[0m", file);
            }
        }
    }

    if !is_field_disabled(&opts.disabled_fields, "size") {
        println!("\x1b[37;1mSize\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{} ({} files)\x1b[0m", 
            info.repo_size, info.file_count);
    }

    if !is_field_disabled(&opts.disabled_fields, "contributors") && info.total_authors > 1 {
        println!("\x1b[37;1mContributors\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{}\x1b[0m", 
            info.total_authors);
    }

    println!();

    // Print color palette
    if !opts.no_color_palette {
        for color in 0..8 {
            print!("\x1b[4{}m   \x1b[49m", color);
        }
        println!();
    }

    // Print escape sequence reset
    print!("\x1b[?7h");
    std::io::stdout().flush().ok();

    Ok(())
}

fn output_json(info: &RepoInfo) -> Result<(), String> {
    // Simplified JSON output
    println!("{{");
    println!("  \"title\": {{");
    println!("    \"gitUsername\": \"{}\",", info.git_user);
    println!("    \"gitVersion\": \"{}\"", info.git_version);
    println!("  }},");
    println!("  \"infoFields\": [");

    // Add various info fields
    println!("    {{");
    println!("      \"HeadInfo\": {{");
    println!("        \"headRefs\": {{");
    println!("          \"shortCommitId\": \"{}\",", info.current_commit);
    println!("          \"refs\": [\"{}\"]\n        }}", info.current_branch);
    println!("      }}");
    println!("    }}");

    println!("  ]");
    println!("}}");

    Ok(())
}

fn is_field_disabled(disabled: &[String], field: &str) -> bool {
    disabled.iter().any(|f| f.to_lowercase() == field.to_lowercase())
}

