        return;
    }

    // Check for --generate flag
    for (i, arg) in args.iter().enumerate() {
        if (arg == "--generate" || arg == "-g") && i + 1 < args.len() {
            print_completions(&args[i + 1]);
            return;
        }
    }

    // Get the repository path
    let repo_path = get_repo_path(&args);

