    if !is_field_disabled(&opts.disabled_fields, "churn") && !info.files.is_empty() {
        let pool_size = info.files.len().max(1);
        for (i, (file, _)) in info.files.iter().take(opts.number_of_file_churns).enumerate() {
            if i == 0 {
                println!("\x1b[37;1mChurn ({})\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{} 1\x1b[0m", 
                    pool_size, file);
            } else {
                println!("         \x1b[39m{} 1\x1b[0m", file);
            }
        }
    }

    if !is_field_disabled(&opts.disabled_fields, "size") {
        println!("\x1b[37;1mSize\x1b[0m\x1b[39;1m:\x1b[0m \x1b[39m{} ({} files)\x1b[0m", 
            info.repo_size, info.file_count);
    }

